<script setup lang="ts">
import { computed } from 'vue'

// Simple icon component with inline SVGs
const props = defineProps<{
  name?: string  // New prop name
  icon?: string  // Keep for backward compatibility
  /** §POCKETBRIDGE P0 — accept Vue's full class-binding shapes. Declaring this
   *  as bare `string` made every object binding (`:class="{ spin: busy }"`) a
   *  type error — 19 of them across the app — while working fine at runtime. */
  class?: string | Record<string, boolean> | Array<string | Record<string, boolean>>
  /** Accessible name. When provided, the icon is exposed to assistive tech
   *  as role="img" with this label. When omitted (the default), the icon is
   *  treated as decorative and hidden from screen readers via aria-hidden —
   *  so it never pollutes the AT tree, and icon-only buttons rely on their
   *  own aria-label instead. */
  label?: string
}>()

// Use either name or icon prop
const iconName = computed(() => props.name || props.icon || '')

