<template>
  <span
    v-html="icons[iconName] || ''"
    :class="class"
    class="icon-wrap"
    :role="label ? 'img' : undefined"
    :aria-label="label || undefined"
    :aria-hidden="label ? undefined : 'true'"
  ></span>
</template>

<style scoped>
/* Default icon sizing — without this, raw inline SVGs (no width/height attrs)
   render at the browser default of 300×150, which made the inline shield in
   the BuyAVT confirm preview look like a billboard. Constraining the wrapper
   span + the inner svg to 1em × 1em makes every Icon track the surrounding
   text size by default. Callers that want a larger icon can override via
   :class="..." with a font-size or width/height rule. */
.icon-wrap {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1em;
  height: 1em;
  line-height: 1;
  vertical-align: -0.125em;
  flex-shrink: 0;
}
.icon-wrap :deep(svg) {
  width: 1em;
  height: 1em;
  display: block;
}
</style>
